package com.ruoyi.ai.agent;

import com.fasterxml.jackson.databind.node.*;
import junit.framework.TestCase;
import static com.ruoyi.ai.agent.AgentJson.*;

public class B8bMergeManifestTest extends TestCase {
    private ObjectNode snapshot(){return (ObjectNode)parse("{\"id\":\"p\",\"sheetOrder\":[\"s\"],\"sheets\":{\"s\":{\"id\":\"s\",\"name\":\"Sheet\",\"rowCount\":6,\"columnCount\":6,\"cellData\":{\"0\":{\"0\":{\"v\":\"top\",\"t\":1}},\"3\":{\"3\":{\"v\":\"outside\",\"t\":1}}},\"mergeData\":[]}}}");}
    private ArrayNode scopes(){return (ArrayNode)parse("[{\"sheetId\":\"s\",\"range\":\"A1:B2\"}]");}
    private ObjectNode action(String type){return (ObjectNode)parse("{\"schemaVersion\":\"2.0\",\"type\":\""+type+"\",\"target\":{\"sheetId\":\"s\",\"range\":\"A1:B2\"}}");}
    private void reject(Runnable r){try{r.run();fail("unsafe merge accepted");}catch(IllegalArgumentException expected){assertNotNull(expected.getMessage());}}
    public void testGateMergeBreakApartAndOutside(){ObjectNode first=snapshot(),a=action("merge");assertFalse(WriteManifest.availableActions(true,false,false).contains("merge"));assertTrue(WriteManifest.availableActions(true,false,false,true).contains("merge"));reject(()->WriteManifest.classify(arr().add(a),true,false,false));assertEquals("controlled-values",WriteManifest.classify(arr().add(a),true,false,false,true));ObjectNode m=MergeManifest.preview(first,a,scopes()),merged=MergeManifest.apply(first,m);assertEquals(1,merged.path("sheets").path("s").path("mergeData").size());assertEquals(first.path("sheets").path("s").path("cellData").path("3"),merged.path("sheets").path("s").path("cellData").path("3"));ObjectNode b=MergeManifest.preview(merged,action("breakApart"),scopes()),broken=MergeManifest.apply(merged,b);assertEquals(0,broken.path("sheets").path("s").path("mergeData").size());assertEquals(first.path("sheets").path("s").path("cellData"),broken.path("sheets").path("s").path("cellData"));}
    public void testLossRequiresForceAndPatch(){ObjectNode first=snapshot();((ObjectNode)first.path("sheets").path("s").path("cellData").path("0")).set("1",obj().put("v","loss").put("t",1));ObjectNode action=action("merge");reject(()->MergeManifest.preview(first,action,scopes()));action.put("force",true);ObjectNode m=MergeManifest.preview(first,action,scopes());assertEquals("loss",m.path("mergePatch").path("removedCells").get(0).path("before").path("v").asText());ObjectNode next=MergeManifest.apply(first,m);assertTrue(next.path("sheets").path("s").path("cellData").path("0").path("1").isMissingNode());assertEquals("outside",next.path("sheets").path("s").path("cellData").path("3").path("3").path("v").asText());ObjectNode rich=first.deepCopy();((ObjectNode)rich.path("sheets").path("s").path("cellData").path("0").path("1")).set("s",obj().put("bg",obj().put("rgb","#abcdef")));reject(()->MergeManifest.preview(rich,action,scopes()));}
    public void testOverlapPartialBreakAndForgery(){ObjectNode first=snapshot(),m=MergeManifest.preview(first,action("merge"),scopes()),merged=MergeManifest.apply(first,m);reject(()->MergeManifest.preview(merged,action("merge"),scopes()));ObjectNode partial=action("breakApart");((ObjectNode)partial.path("target")).put("range","A1:A2");reject(()->MergeManifest.preview(merged,partial,scopes()));ObjectNode forged=m.deepCopy();((ObjectNode)forged.path("mergePatch")).put("range","C1:D2");reject(()->MergeManifest.apply(first,forged));reject(()->MergeManifest.validateReceipt(m,obj().put("sheetId","s")));}
    public void testSavedVerification(){ObjectNode m=MergeManifest.preview(snapshot(),action("merge"),scopes()),saved=MergeManifest.apply(snapshot(),m);ObjectNode change=obj().put("kind","controlled-merge").put("operationId","call").put("afterHash",hash(saved));change.set("mergePatch",m.path("mergePatch"));ObjectNode write=obj().put("transportVersion",2).put("callId","call").put("persistenceStatus","SAVED").put("validation","PASSED").put("loadedRevision",hash(saved)).put("sourceRevision",hash(saved));write.set("executedChange",change);write.set("actions",m.path("actions"));ObjectNode args=obj().put("kind","matches_merge").put("sheetId","s").put("range","A1:B2");args.set("write",write);assertTrue(AgentTools.verify(saved,args).path("passed").asBoolean());((ObjectNode)saved.path("sheets").path("s")).set("mergeData",arr());String forgedHash=hash(saved);write.put("loadedRevision",forgedHash).put("sourceRevision",forgedHash);change.put("afterHash",forgedHash);reject(()->AgentTools.verify(saved,args));}
    public void testMergeAndBreakApartHaveDistinctEffectTargets(){ObjectNode first=snapshot(),merge=MergeManifest.preview(first,action("merge"),scopes()),split=MergeManifest.preview(MergeManifest.apply(first,merge),action("breakApart"),scopes());assertFalse(StableEffectLedger.identity(merge).path("semanticKey").equals(StableEffectLedger.identity(split).path("semanticKey")));}
}
